///
/// Generic form only (directive `operands`).
#[mlir::op("tosa.transpose", results(output))]
pub struct TransposeOp<'a> {
    #[slot(input1_ty)]
    pub input1: Value<'a>,
    #[attr(dense = "i32")]
    pub perms: Attribute<'a>,
    #[dtype]
    pub input1_ty: Type<'a>,
    #[dtype]
    pub output: Type<'a>,
}

/// `tosa.variable`: Defines a variable
///
/// Defines a new TOSA variable. This is a persistent mutable value across multiple
/// TOSA graph invocations. Modifications are expressed using read/write semantics.
///
/// Generic form only (custom C++ syntax).
#[mlir::op("tosa.variable")]
pub struct VariableOp<'a> {
    #[attr(symbol)]
    pub sym_name: Attribute<'a>,
    #[attr]
    pub var_shape: Attribute<'a>,
    #[attr(name = "type")]
    pub type_: Attribute<'a>,
    #[attr]
    pub initial_value: Option<Attribute<'a>>,
}

/// `tosa.variable_read`: read_buffer operator
///
/// Reads the value from a pseudo-buffer resource holding a persistent mutable tensor.
#[mlir::op("tosa.variable_read", format = "$name attr-dict `:` type($output1)", results(output1))]
pub struct VariableReadOp<'a> {
    #[attr(symbol)]
    pub name: Attribute<'a>,
    #[dtype]
    pub output1: Type<'a>,
}

/// `tosa.variable_write`: write_buffer operator
///
/// Assigns a value to the pseudo-buffer resource holding a persistent mutable tensor.
#[mlir::op("tosa.variable_write", format = "$name attr-dict `,` $input1 `:` type($input1)")]
pub struct VariableWriteOp<'a> {
    #[slot(input1_ty)]
    pub input1: Value<'a>,
    #[attr(symbol)]
    pub name: Attribute<'a>,
    #[dtype]
    pub input1_ty: Type<'a>,
}

/// `tosa.while_loop`: output = input; While (Cond(output)) {output = Body(output)}
///
/// Generates and evaluates a Boolean condition and either executes a loop body
/// or exits the loop. This action is performed repeatedly after
/// updating and re-evaluating the Boolean condition every iteration. This
/// implements the semantic foreach or while iterative loop structure.
///
/// Generic form only (custom C++ syntax).
#[mlir::op("tosa.while_loop", results(output_list))]
pub struct WhileOp<'a> {
    #[slot(input_list_ty)]
    pub input_list: Vec<Value<'a>>,
    #[region]
    pub cond_graph: Region<'a>,
    #[region]
    pub body_graph: Region<'a>,
    #[dtype]
    pub input_list_ty: Vec<Type<'a>>,
    #[dtype]
    pub output_list: Vec<Type<'a>>,
}

/// `tosa.yield`: yield operator
///
/// return operation within the conditional and body of
/// structured control flow. Operation takes variadic operands
/// but produces no results of its own.
#[mlir::op("tosa.yield", format = "$inputs attr-dict `:` type($inputs)")]
pub struct YieldOp<'a> {
    #[slot(inputs_ty)]
    pub inputs: Vec<Value<'a>>,
    #[dtype]
    pub inputs_ty: Vec<Type<'a>>,
}

/// The `tosa` dialect.
#[mlir::dialect(
    "tosa",
    ops = [AbsOp, AddOp, AddShapeOp, ApplyScaleOp, ArgMaxOp, ArithmeticRightShiftOp, AvgPool2dOp, BitwiseAndOp, BitwiseNotOp, BitwiseOrOp, BitwiseXorOp, CastFromBlockScaledOp, CastOp, CastToBlockScaledOp, CeilOp, ClampOp, ClzOp, ConcatOp, ConcatShapeOp, ConstOp, ConstShapeOp, Conv2DOp, Conv3DOp, CosOp, CustomOp, DepthwiseConv2DOp, DimOp, DivCeilShapeOp, DivFloorShapeOp, EqualOp, ErfOp, Exp2ShapeOp, ExpOp, FFT2dOp, FloorOp, GatherOp, GreaterEqualOp, GreaterOp, IdentityOp, IfOp, IntDivOp, Log2CeilShapeOp, Log2FloorShapeOp, LogOp, LogicalAndOp, LogicalLeftShiftOp, LogicalNotOp, LogicalOrOp, LogicalRightShiftOp, LogicalXorOp, MatMulOp, MatmulTBlockScaledOp, MaxPool2dOp, MaxShapeOp, MaximumOp, MinShapeOp, MinimumOp, ModShapeOp, MulOp, MulShapeOp, NegateOp, PadOp, PowOp, RFFT2dOp, ReciprocalOp, ReduceAllOp, ReduceAnyOp, ReduceMaxOp, ReduceMinOp, ReduceProductOp, ReduceSumOp, RescaleOp, ReshapeOp, ResizeOp, ReverseOp, RsqrtOp, ScatterOp, SelectOp, SigmoidOp, SinOp, SliceOp, SliceShapeOp, SubOp, SubShapeOp, TableOp, TanhOp, TileOp, TransposeConv2DOp, TransposeOp, VariableOp, VariableReadOp, VariableWriteOp, WhileOp, YieldOp],
    dependents = ["tensor", "quant"],
    materializer
)]
pub struct TosaDialect;
